import {infrastructure, mountInfrastructure} from './infrastructure.js';
import {content, industries, sources, rawWorkUrl, simulation} from './content.js';
const main = document.querySelector('main');
const escape = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = s => {try {const u=new URL(s,location.href); return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}};
const pending = '<span class="status"><i></i> RESEARCH IN PROGRESS</span>';
const section = (id,number,title,body,cls='') => `<section id="${id}" class="section ${cls}"><div class="section-label"><span>${number}</span><span>${title}</span></div>${body}</section>`;
const placeholder = (title,text) => `<div class="placeholder">${pending}<h3>${title}</h3><p>${text}</p></div>`;
// Use citation('source-id') in research copy once its matching bibliography record exists.
export const citation = id => sources.some(s=>s.id===id)?`<a class="citation" href="#research/source-${encodeURIComponent(id)}">[${escape(id)}]</a>`:'';
function industryLandscape(){return section('industries','01 / THE LANDSCAPE','Industry feasibility',`<div class="section-heading"><h2>A NEW FRONTIER.<br>NOT A FREE PASS.</h2><p>Compare the opportunity with what still has to work.<br>Candidate industries below are starting points for research.</p></div><div class="table-scroll" tabindex="0" role="region" aria-label="Industry feasibility matrix"><table><thead><tr><th>Industry</th><th>Microgravity advantage</th><th>Remaining barrier</th><th>Verdict</th></tr></thead><tbody>${industries.map((x,i)=>`<tr><td><span class="row-number">0${i+1}</span>${escape(x)}</td><td>To be researched</td><td>To be researched</td><td><span class="tag">PENDING</span></td></tr>`).join('')}</tbody></table></div>`)+
section('potential','02 / OPPORTUNITIES','Potential industries',`<div class="section-heading"><h2>WHAT COULD<br>WORK?</h2><p>The current candidates are listed in the matrix above. Their potential still needs to be established through research.</p></div>${placeholder('Potential industries are under review.','Compare each candidate’s microgravity advantage, usable output, and production and return costs before adding it to the shortlist.')}`)+
section('not-viable','03 / LIMITS','Industries that don’t work',`<div class="section-heading"><h2>WHERE THE CASE<br>BREAKS DOWN.</h2><p>Free launch alone does not settle feasibility.</p></div>${placeholder('No industries ruled out yet.','This section will collect industries the evidence rules out, with the barriers and assumptions behind each conclusion.')}`);}
function economy(){return section('brief','01 / THE PREMISE','A different cost of entry',`<div class="brief-grid"><h2>FREE TO LAUNCH.<br>WHAT’S WORTH<br>MAKING?</h2><div><p class="large">Tomorrow, launching mass to orbit becomes effectively free.</p><p>What industries become possible, which still don’t make sense, and what is the first product that will be fundamentally cheaper to make in microgravity?</p><p>At what launch, manufacturing, and return costs is it viable?</p><span class="small-note">CHALLENGE PROMPT · ANALYSIS FORTHCOMING</span></div></div>`)+
section('medicine','02 / SPACE MEDICINE','A closer look',`<div class="split"><div><h2>SMALL CELLS.<br>BIG QUESTIONS.</h2><p>Investigating the case for manufacturing medicine in microgravity.</p><a class="button" href="#economy/simulation">EXPLORE THE SIMULATION <span>↓</span></a></div><div class="research-list">${[['01','The biological advantage','What changes in orbit, and what has actually been measured?'],['02','From experiment to production','Can quality and usable yield persist at commercial scale?'],['03','The journey home','What survives return, testing, storage, and delivery?']].map(([n,t,d])=>`<details><summary><span>${n}</span>${t}<b>+</b></summary><p>${d}</p><p class="muted">Research and in-text citations to be added by the team.</p></details>`).join('')}</div></div>`)+
section('simulation','03 / INTERACTIVE LAB','Space medicine simulation',`<div class="section-heading"><h2>SEE THE SCIENCE.</h2><p>A dedicated space for the team’s simulation.<br>Integration is pending delivery of the simulation code.</p></div><div id="simulation-mount" class="simulation"><div class="orbital-art" aria-hidden="true"><div class="orbital-ring"></div><div class="orbital-ring second"></div><div class="orbital-core"></div></div><div class="sim-caption"><span class="tag">SIMULATION COMING SOON</span><h3>FROM EARTH TO ORBIT.</h3><p>The interactive model will appear here.</p></div><span class="visual-note">CONCEPT ILLUSTRATION · NOT SIMULATED DATA</span></div>`)+
section('calculator','04 / THE ECONOMICS','Stem-cell feasibility calculator',`<div class="section-heading"><h2>THE NUMBERS<br>HAVE TO WORK.</h2><p>Define the assumptions. Compare the costs.<br>Find the break-even point.</p></div><div class="calc-intro"><p class="large">What will be cheaper to make in space first? We think it&rsquo;s heart-muscle cells grown from stem cells.</p><p>Labs grow stem cells and then coax them into the specialized cells a patient needs, such as heart-muscle cells. On Earth, many batches lose cells to the wrong cell type, and every wasted cell carries the cost of expensive growth media, clean rooms and skilled staff. In microgravity, cells float freely in 3D. Lab experiments that imitate microgravity have produced 1.5 to 4 times more working heart cells per starting stem cell than the best 3D culture on Earth. Our calculator turns that into dollars per patient dose (about 150 million heart cells). On today&rsquo;s Space Station, space costs about 5 times more ($100,476 vs $19,552), mostly because of astronaut time, launch and the trip home. With three changes, space comes out cheaper at $14,854 per dose, 24% below Earth:</p><ul><li>cells grow about 3 times better</li><li>an automated factory satellite replaces astronauts</li><li>cheaper rockets and shared return capsules</li></ul><p>It stays cheaper as long as launch costs under about $7,200 per kg, the return trip costs under about $255,000 per batch, and microgravity delivers at least 2.3 times more cells. Every assumption in the calculator is rated against published research, so you can see which numbers are proven and which are bets. Across the full range of uncertainty, space wins in about half of modeled scenarios.</p></div><div class="calc-embed"><iframe id="calc-frame" title="Stem-cell cost calculator: Earth vs space" src="calculator/pitch.html?embed=1&amp;theme=dark&amp;skin=bagel"></iframe></div><a class="button calc-full" href="calculator/index.html" target="_blank" rel="noopener">OPEN THE FULL CALCULATOR: EVERY ASSUMPTION AND SOURCE <span>&nearr;</span></a>`)+verdict('economy','05');}
function verdict(tab,n){return section('verdict',`${n} / THE VERDICT`,'Where we land',`<div class="split"><div><h2>${tab==='economy'?'WHAT COMES<br>FIRST?':'WHAT HOLDS<br>UP IN ORBIT?'}</h2><p>Our answer will follow the evidence.</p></div><div>${placeholder('The conclusion is still being written.','This section will bring together the thesis, the conditions required for it to hold, and the strongest counterargument.')}<a class="text-link" href="${tab==='economy'?'#infrastructure':'#research'}">${tab==='economy'?'NEXT: ORBITAL ECONOMY':'EXPLORE THE RESEARCH'} <span>↗</span></a></div></div>`);}
function research(){return `<section class="research-document" aria-label="Research document"><iframe title="Orbital Economy research Google Doc" src="${escape(safeUrl(rawWorkUrl.replace(/\/edit.*$/, '/preview')))}"></iframe></section>`;}
let current='', cleanup=null, renderGeneration=0;
// Size the embedded calculator (same-origin, dist/calculator/) to its content so it never shows an inner scrollbar.
function mountCalculator(){const frame=document.querySelector('#calc-frame');if(!frame)return;const fit=()=>{try{const d=frame.contentDocument;if(d&&d.body)frame.style.height=Math.ceil(d.body.getBoundingClientRect().height)+'px';}catch{}};const later=()=>setTimeout(fit,60);const wire=()=>{fit();try{const w=frame.contentWindow,d=frame.contentDocument;new w.ResizeObserver(fit).observe(d.body);['click','input','keydown'].forEach(e=>d.addEventListener(e,later));w.addEventListener('resize',later);}catch{}};frame.addEventListener('load',wire);if(frame.contentDocument?.readyState==='complete'&&frame.contentDocument.body?.childElementCount)wire();}
async function mountSimulation(generation){const el=document.querySelector('#simulation-mount');if(!el)return;try{if(simulation.iframeUrl&&safeUrl(simulation.iframeUrl)){el.replaceChildren();const frame=document.createElement('iframe');frame.title=simulation.title;frame.src=safeUrl(simulation.iframeUrl);frame.sandbox='allow-scripts allow-same-origin';frame.loading='lazy';el.append(frame);}else if(simulation.moduleUrl){const module=await import(simulation.moduleUrl);if(generation!==renderGeneration)return;el.replaceChildren();const result=await module.mount(el);if(generation!==renderGeneration){if(typeof result==='function')result();return;}cleanup=typeof result==='function'?result:null;}}catch(e){if(generation===renderGeneration)el.innerHTML=placeholder('Simulation unavailable.','The simulation could not load. Please try reloading the page.');console.error(e);}}
function route(){let [tab='industries',id]=location.hash.slice(1).split('/');if(!content[tab]){location.replace('#industries');return;}if(current!==tab){cleanup?.();cleanup=null;current=tab;const generation=++renderGeneration,c=content[tab];main.innerHTML=tab==='research'?research():`<div class="hero hero-${tab}" style="--hero:url('${c.image}')"><div class="hero-content"><span class="eyebrow">${c.eyebrow}</span><h1>${c.title.replaceAll('\n','<br>')}</h1><p>${c.description}</p><a class="button" href="#${tab}/${c.sections[0][0]}">${tab==='research'?'EXPLORE OUR WORK':'EXPLORE THE QUESTION'} <span>↓</span></a></div><div class="hero-bottom"><span>THE ORBITAL ECONOMY</span><a href="#${tab}/${c.sections[0][0]}" aria-label="Scroll to content">⌄</a><span>${tab==='research'?'RESEARCH & TEAM':`${c.number} / 03`}</span></div></div><nav class="section-nav" aria-label="Section navigation">${c.sections.map(([i,l])=>`<a href="#${tab}/${i}">${l}</a>`).join('')}</nav>${tab==='industries'?industryLandscape():tab==='economy'?economy():tab==='infrastructure'?infrastructure():research()}`;document.title=`${c.label} — The Orbital Economy`;mountSimulation(generation);if(tab==='economy')mountCalculator();if(tab==='infrastructure')mountInfrastructure();}
document.querySelectorAll('[data-tab]').forEach(a=>{const active=a.dataset.tab===tab;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});document.querySelector('#navigation').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');requestAnimationFrame(()=>{const target=id?document.getElementById(id):null;if(target)target.scrollIntoView({behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'});});}
window.addEventListener('hashchange',route);document.querySelector('#menu-toggle').addEventListener('click',e=>{const open=document.querySelector('#navigation').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('#navigation').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');}});document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});document.querySelector('#print').addEventListener('click',()=>window.print());window.addEventListener('scroll',()=>document.querySelector('header').classList.toggle('scrolled',scrollY>40),{passive:true});route();
